insert into public.experiences(id,product_id,name,display_order,is_active,metadata) values('cbee4b4a-1169-4108-820e-1e87b5db4057','b262ffa8-9912-4eba-93d7-58af3164d1cc','TOEFL iBT Practice Test 1 (2026 format)',0,true,'{"format":"toefl-2026","catalog":"full_test","launch_pack":"toefl_2026_v1","content_revision":"original-2026-10-v1","duration_seconds":5400,"original_content":true,"adaptive":{"router_threshold":0.6,"modules":"router + lower/upper"}}'::jsonb) on conflict (id) do nothing;
insert into public.sections(id,experience_id,name,display_order,metadata) values('d1e3c533-f6c5-4d12-a772-beff6dfdab53','cbee4b4a-1169-4108-820e-1e87b5db4057','Reading: Module 1',1,'{"format":"toefl-2026","duration_mode":"fixed","type":"reading","toefl_module":"router","duration_seconds":1260,"item_count":30}'::jsonb) on conflict (id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('4e684463-fa99-4af8-bc87-2b5c3ffcd6d2','d1e3c533-f6c5-4d12-a772-beff6dfdab53','Complete the Words',1,'{"toefl_task":"complete_the_words"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d986b7bc-bdba-49f9-89cf-6e6a987d7d72','4e684463-fa99-4af8-bc87-2b5c3ffcd6d2','question_complete_words','{"prompt":"Fill in the missing letters in the paragraph.","text":"Archaeologists often learn more from ancient rubbish than from grand monuments. When {{1}} threw {{2}} broken {{3}}, animal {{4}}, and {{5}} seeds, {{6}} created a {{7}} of {{8}} life {{9}} nobody {{10}} to keep. By studying the layers of a waste pit, researchers can tell which foods were common, how cooking methods changed, and even when trade with distant regions began. Because these objects were never meant to impress anyone, they often give a more honest picture of the past than official records do.","blanks":[{"id":"1","stem":"peo","length":3},{"id":"2","stem":"aw","length":2},{"id":"3","stem":"po","length":2},{"id":"4","stem":"bo","length":3},{"id":"5","stem":"bu","length":3},{"id":"6","stem":"th","length":2},{"id":"7","stem":"rec","length":3},{"id":"8","stem":"da","length":3},{"id":"9","stem":"th","length":2},{"id":"10","stem":"inte","length":4}],"topic":"archaeology"}'::jsonb,1,'{"toefl_task":"complete_the_words","original_slug":"cw-router-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d986b7bc-bdba-49f9-89cf-6e6a987d7d72','{"blanks":{"1":"ple","2":"ay","3":"ts","4":"nes","5":"rnt","6":"ey","7":"ord","8":"ily","9":"at","10":"nded"},"stems":{"1":"peo","2":"aw","3":"po","4":"bo","5":"bu","6":"th","7":"rec","8":"da","9":"th","10":"inte"},"words":{"1":"people","2":"away","3":"pots","4":"bones","5":"burnt","6":"they","7":"record","8":"daily","9":"that","10":"intended"}}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Full paragraph: Archaeologists often learn more from ancient rubbish than from grand monuments. When people threw away broken pots, animal bones, and burnt seeds, they created a record of daily life that nobody intended to keep. By studying the layers of a waste pit, researchers can tell which foods were common, how cooking methods changed, and even when trade with distant regions began. Because these objects were never meant to impress anyone, they often give a more honest picture of the past than official records do."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('0839fec4-3e8b-40b5-bca2-3c571c9c7c45','d1e3c533-f6c5-4d12-a772-beff6dfdab53','Complete the Words',2,'{"toefl_task":"complete_the_words"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b1a809bd-4897-46f9-9d2c-72ab91e8569e','0839fec4-3e8b-40b5-bca2-3c571c9c7c45','question_complete_words','{"prompt":"Fill in the missing letters in the paragraph.","text":"Clouds form when warm, moist air rises and cools. As {{1}} air {{2}} higher, {{3}} expands {{4}} the {{5}} around {{6}} becomes {{7}}, and {{8}} expansion {{9}} the {{10}} lose heat. Cooler air cannot hold as much water vapor, so tiny droplets begin to gather around small particles of dust or salt. Millions of these droplets together become visible as a cloud. If the droplets keep growing and become too heavy to stay in the air, they finally fall to the ground as rain or snow.","blanks":[{"id":"1","stem":"t","length":2},{"id":"2","stem":"cli","length":3},{"id":"3","stem":"i","length":1},{"id":"4","stem":"bec","length":4},{"id":"5","stem":"pres","length":4},{"id":"6","stem":"i","length":1},{"id":"7","stem":"lo","length":3},{"id":"8","stem":"th","length":2},{"id":"9","stem":"ma","length":3},{"id":"10","stem":"a","length":2}],"topic":"earth science"}'::jsonb,1,'{"toefl_task":"complete_the_words","original_slug":"cw-router-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('b1a809bd-4897-46f9-9d2c-72ab91e8569e','{"blanks":{"1":"he","2":"mbs","3":"t","4":"ause","5":"sure","6":"t","7":"wer","8":"is","9":"kes","10":"ir"},"stems":{"1":"t","2":"cli","3":"i","4":"bec","5":"pres","6":"i","7":"lo","8":"th","9":"ma","10":"a"},"words":{"1":"the","2":"climbs","3":"it","4":"because","5":"pressure","6":"it","7":"lower","8":"this","9":"makes","10":"air"}}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Full paragraph: Clouds form when warm, moist air rises and cools. As the air climbs higher, it expands because the pressure around it becomes lower, and this expansion makes the air lose heat. Cooler air cannot hold as much water vapor, so tiny droplets begin to gather around small particles of dust or salt. Millions of these droplets together become visible as a cloud. If the droplets keep growing and become too heavy to stay in the air, they finally fall to the ground as rain or snow."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('ef9111a9-6ead-4be7-b63b-68b007a6abbf','d1e3c533-f6c5-4d12-a772-beff6dfdab53','Read in Daily Life',3,'{"toefl_task":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e2252507-94d9-4e3f-873d-23679ea03e95','ef9111a9-6ead-4be7-b63b-68b007a6abbf','reading_passage','{"toefl_stimulus":"daily_life","format":"notice","title":"Read a notice.","heading":"Makerspace: New Booking Rules","text":"Starting Monday, March 3, the 3D printers in the Riverside Library Makerspace can be used by appointment only. Book a time slot at the front desk or on the library website up to seven days in advance. Each person may reserve a maximum of two hours per week.\n\nIf you are more than 15 minutes late, your slot will be given to the next person on the waiting list. Printing materials are still free, but large projects that need more than one spool must be approved by staff first."}'::jsonb,1,'{"original_slug":"rdl-router-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a9bd7ced-e3e8-4d10-8a96-84d46e5e9ffe','ef9111a9-6ead-4be7-b63b-68b007a6abbf','question_single_choice','{"prompt":"What is the main purpose of the notice?","options":[{"id":"A","label":"To announce that the 3D printers are being replaced"},{"id":"B","label":"To explain a new system for using the printers"},{"id":"C","label":"To invite people to a printing workshop"},{"id":"D","label":"To report that printing materials are no longer free"}]}'::jsonb,2,'{"toefl_task":"read_daily_life","original_slug":"rdl-router-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a9bd7ced-e3e8-4d10-8a96-84d46e5e9ffe','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The notice explains that the printers can now be used ''by appointment only'' and gives the booking rules, so B is correct. Nothing says the printers are being replaced (A) or mentions a workshop (C). D is the opposite of the text, which says materials ''are still free''."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f9eb5b2e-e835-4132-97b8-c52305566beb','ef9111a9-6ead-4be7-b63b-68b007a6abbf','question_single_choice','{"prompt":"What will happen if a user arrives 20 minutes after the start of a reserved slot?","options":[{"id":"A","label":"The user will have to pay a fee."},{"id":"B","label":"The user''s weekly limit will be reduced."},{"id":"C","label":"The user will only be allowed to print small projects."},{"id":"D","label":"The time slot may go to someone else."}]}'::jsonb,3,'{"toefl_task":"read_daily_life","original_slug":"rdl-router-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('f9eb5b2e-e835-4132-97b8-c52305566beb','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Users who are more than 15 minutes late lose their slot to the next person on the waiting list, so D is correct. The notice mentions no late fee (A) and no change to the two-hour weekly limit (B). Project size (C) is connected to staff approval, not to lateness."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('6ef6cf91-c722-492d-af1d-cbbdb45d3b35','d1e3c533-f6c5-4d12-a772-beff6dfdab53','Read in Daily Life',4,'{"toefl_task":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('365375da-c97b-4821-92e8-42ead8406ab1','6ef6cf91-c722-492d-af1d-cbbdb45d3b35','reading_passage','{"toefl_stimulus":"daily_life","format":"email","title":"Read an email.","heading":null,"text":"Hi everyone,\n\nA quick update about Saturday''s trip to Cedar Ridge. Because of road repairs on Elm Avenue, the bus can''t pick us up in front of the Science Building as planned. Instead, please meet at the north entrance of the Student Center (next to the bike racks). The departure time hasn''t changed: we leave at 8:00 a.m. sharp, so aim to be there ten minutes early.\n\nThe forecast calls for rain in the afternoon, so bring a waterproof jacket and sturdy shoes. Lunch will be provided, but feel free to pack snacks.\n\nIf you can no longer attend, let me know by Thursday so I can offer your seat to someone on the waiting list.\n\nThanks,\nPriya","email":{"from":"Priya Natarajan, Field Studies Coordinator","to":"Students in GEOL 105","subject":"Saturday trip: change of meeting point"}}'::jsonb,1,'{"original_slug":"rdl-router-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4e4b92b1-783a-406c-9f17-aebe48156088','6ef6cf91-c722-492d-af1d-cbbdb45d3b35','question_single_choice','{"prompt":"Why did Priya write the email?","options":[{"id":"A","label":"To announce that the trip has been postponed"},{"id":"B","label":"To ask students to suggest a departure time"},{"id":"C","label":"To tell students about a different place to gather"},{"id":"D","label":"To explain why the bus company was changed"}]}'::jsonb,2,'{"toefl_task":"read_daily_life","original_slug":"rdl-router-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('4e4b92b1-783a-406c-9f17-aebe48156088','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The subject line and first paragraph explain that students must meet at the Student Center instead of the Science Building, so C is correct. The trip is still on Saturday (A), the departure time ''hasn''t changed'' (B), and no new bus company is mentioned (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a8258dd1-a143-470f-b1dd-93043c75fe16','6ef6cf91-c722-492d-af1d-cbbdb45d3b35','question_single_choice','{"prompt":"What are students advised to bring?","options":[{"id":"A","label":"Clothing suitable for wet weather"},{"id":"B","label":"A packed lunch"},{"id":"C","label":"Their own bicycle"},{"id":"D","label":"A printed map of Cedar Ridge"}]}'::jsonb,3,'{"toefl_task":"read_daily_life","original_slug":"rdl-router-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a8258dd1-a143-470f-b1dd-93043c75fe16','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Because rain is expected, Priya tells students to bring a waterproof jacket and sturdy shoes, so A is correct. Lunch will be provided, so B is wrong. The bike racks only describe the meeting place (C), and no map is mentioned (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('cb23ac69-fa6e-4f3d-a8ef-034f6a0eee27','6ef6cf91-c722-492d-af1d-cbbdb45d3b35','question_single_choice','{"prompt":"What can be inferred about the trip?","options":[{"id":"A","label":"It will end before the rain begins."},{"id":"B","label":"It was originally planned for Thursday."},{"id":"C","label":"Students must pay extra for the bus."},{"id":"D","label":"More students want to go than there are seats."}]}'::jsonb,4,'{"toefl_task":"read_daily_life","original_slug":"rdl-router-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('cb23ac69-fa6e-4f3d-a8ef-034f6a0eee27','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Priya mentions a waiting list for seats, which suggests demand is greater than the number of places, so D is correct. She warns about afternoon rain, so A is not supported. Thursday is only the deadline for cancelling (B), and no cost is mentioned (C)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('f688e30c-f933-4e98-8d22-26fe43af0717','d1e3c533-f6c5-4d12-a772-beff6dfdab53','Read an Academic Passage',5,'{"toefl_task":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e4c08b2b-acbe-4b7e-a1dc-3bf501957b0a','f688e30c-f933-4e98-8d22-26fe43af0717','reading_passage','{"toefl_stimulus":"academic_passage","title":"Why Many Songbirds Migrate at Night","text":"Every spring and autumn, millions of small songbirds travel thousands of kilometers between their breeding and wintering grounds. Surprisingly, many of these species, which are active only during the day for the rest of the year, make their long journeys at night. Researchers have proposed several explanations for this change in behavior.\n\nOne explanation concerns temperature and water. Flying requires intense muscular effort, which generates a great deal of heat. In the cooler night air, birds can release this heat more easily and lose less water through breathing, allowing them to fly longer without becoming dehydrated. Night air is also usually calmer, so birds spend less energy struggling against strong, unpredictable winds.\n\nA second explanation focuses on feeding. Small birds cannot carry large fat reserves, so they must stop regularly to refuel. By flying at night, they keep the daylight hours free for searching for insects and seeds. In addition, darkness offers some protection from hawks and falcons, which hunt by sight. Finally, the night sky itself may help: experiments suggest that young birds learn the pattern of stars around the point in the sky that does not appear to move, and later use it to hold their direction.","subject":"life science"}'::jsonb,1,'{"original_slug":"ap-router-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","toefl_stimulus":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3a76017b-ba31-40e6-b35a-d57bade8249f','f688e30c-f933-4e98-8d22-26fe43af0717','question_single_choice','{"prompt":"According to paragraph 2, how does cooler night air help migrating birds?","options":[{"id":"A","label":"It makes insects easier to find."},{"id":"B","label":"It allows them to release body heat and lose less water."},{"id":"C","label":"It increases the strength of their muscles."},{"id":"D","label":"It helps them see the stars more clearly."}]}'::jsonb,2,'{"toefl_task":"read_academic_passage","original_slug":"ap-router-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1,"skill":"factual"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('3a76017b-ba31-40e6-b35a-d57bade8249f','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Paragraph 2 says that in cooler air birds ''release this heat more easily and lose less water through breathing'', so B is correct. Insects are found during the day (A), muscle strength is not said to increase (C), and the stars are discussed in paragraph 3, not in connection with cool air (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('78016cd5-81d2-4b76-9aae-619554a94d4c','f688e30c-f933-4e98-8d22-26fe43af0717','question_single_choice','{"prompt":"The word ''reserves'' in the passage is closest in meaning to","options":[{"id":"A","label":"feathers"},{"id":"B","label":"routes"},{"id":"C","label":"appointments"},{"id":"D","label":"stores"}]}'::jsonb,3,'{"toefl_task":"read_academic_passage","original_slug":"ap-router-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2,"skill":"vocabulary"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('78016cd5-81d2-4b76-9aae-619554a94d4c','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"''Fat reserves'' are stores of fat the body keeps for later use, which is why the birds must stop to ''refuel'', so D is correct. Feathers (A) and routes (B) do not fit ''fat'', and ''appointments'' (C) relates to a different meaning of ''reserve''."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7c661d02-e8f7-43b9-a55e-a7b9519a7d60','f688e30c-f933-4e98-8d22-26fe43af0717','question_single_choice','{"prompt":"What can be inferred about hawks and falcons from paragraph 3?","options":[{"id":"A","label":"They are less successful at hunting in the dark."},{"id":"B","label":"They also migrate at night."},{"id":"C","label":"They feed mainly on seeds."},{"id":"D","label":"They use the stars to find their prey."}]}'::jsonb,4,'{"toefl_task":"read_academic_passage","original_slug":"ap-router-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3,"skill":"inference"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('7c661d02-e8f7-43b9-a55e-a7b9519a7d60','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Because these birds ''hunt by sight'', darkness protects small birds from them, which implies they hunt less successfully at night (A). Nothing says they migrate at night (B) or eat seeds (C), and the stars are linked to the songbirds'' direction, not to hunting (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2411240f-b523-4f94-b92b-768006783f12','f688e30c-f933-4e98-8d22-26fe43af0717','question_single_choice','{"prompt":"How does paragraph 3 relate to paragraph 2?","options":[{"id":"A","label":"It challenges the evidence given in paragraph 2."},{"id":"B","label":"It gives an example of the problem described in paragraph 2."},{"id":"C","label":"It presents additional reasons for the same behavior."},{"id":"D","label":"It describes the history of the research in paragraph 2."}]}'::jsonb,5,'{"toefl_task":"read_academic_passage","original_slug":"ap-router-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4,"skill":"relationship"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('2411240f-b523-4f94-b92b-768006783f12','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Paragraph 2 gives one explanation for night migration and paragraph 3 begins ''A second explanation'', adding more reasons, so C is correct. Paragraph 3 does not disagree with paragraph 2 (A), does not illustrate it (B), and does not discuss the history of research (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ed56bad5-4038-4626-988e-f1710af4d5c4','f688e30c-f933-4e98-8d22-26fe43af0717','question_single_choice','{"prompt":"Why does the author mention the point in the sky that does not appear to move?","options":[{"id":"A","label":"To explain why birds cannot migrate on cloudy nights"},{"id":"B","label":"To describe a possible way birds keep their direction at night"},{"id":"C","label":"To show that birds migrate only in the spring"},{"id":"D","label":"To compare birds with human navigators"}]}'::jsonb,6,'{"toefl_task":"read_academic_passage","original_slug":"ap-router-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":5,"skill":"purpose"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('ed56bad5-4038-4626-988e-f1710af4d5c4','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The author says young birds learn the stars around this point and ''later use it to hold their direction'', so B is correct. Cloudy nights (A), the season of migration (C) and human navigators (D) are not discussed in this connection."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.sections(id,experience_id,name,display_order,metadata) values('ff51905c-ec22-4ad8-af3c-99e5b81c4009','cbee4b4a-1169-4108-820e-1e87b5db4057','Reading: Module 2',2,'{"format":"toefl-2026","duration_mode":"fixed","type":"reading","toefl_module":"second","duration_seconds":540,"duration_seconds_by_tier":{"standard":540,"advanced":540},"adaptive_source_section_id":"d1e3c533-f6c5-4d12-a772-beff6dfdab53","adaptive_threshold":0.6,"item_count":20}'::jsonb) on conflict (id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('718eb281-f43d-49a5-a523-b0e3def1a84a','ff51905c-ec22-4ad8-af3c-99e5b81c4009','Complete the Words',1,'{"toefl_task":"complete_the_words","difficulty_tier":"standard"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('437bc2f1-0b1c-4dc8-87df-d54600148f41','718eb281-f43d-49a5-a523-b0e3def1a84a','question_complete_words','{"prompt":"Fill in the missing letters in the paragraph.","text":"Many families keep a small garden behind their homes. Growing {{1}} is a {{2}} way {{3}} save {{4}} and {{5}} eat {{6}} food {{7}} day. {{8}} plants {{9}} sunlight, {{10}} water, and soil that is rich in nutrients. Children often enjoy helping in the garden because they can watch seeds turn into tall green plants over a few weeks. When the vegetables are ready, the whole family can pick them together and cook a simple meal with food they grew themselves.","blanks":[{"id":"1","stem":"veget","length":5},{"id":"2","stem":"go","length":2},{"id":"3","stem":"t","length":1},{"id":"4","stem":"mo","length":3},{"id":"5","stem":"t","length":1},{"id":"6","stem":"fr","length":3},{"id":"7","stem":"ev","length":3},{"id":"8","stem":"Mo","length":2},{"id":"9","stem":"ne","length":2},{"id":"10","stem":"cl","length":3}],"topic":"daily life"}'::jsonb,1,'{"toefl_task":"complete_the_words","original_slug":"cw-lower-1","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"standard"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('437bc2f1-0b1c-4dc8-87df-d54600148f41','{"blanks":{"1":"ables","2":"od","3":"o","4":"ney","5":"o","6":"esh","7":"ery","8":"st","9":"ed","10":"ean"},"stems":{"1":"veget","2":"go","3":"t","4":"mo","5":"t","6":"fr","7":"ev","8":"mo","9":"ne","10":"cl"},"words":{"1":"vegetables","2":"good","3":"to","4":"money","5":"to","6":"fresh","7":"every","8":"Most","9":"need","10":"clean"}}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Full paragraph: Many families keep a small garden behind their homes. Growing vegetables is a good way to save money and to eat fresh food every day. Most plants need sunlight, clean water, and soil that is rich in nutrients. Children often enjoy helping in the garden because they can watch seeds turn into tall green plants over a few weeks. When the vegetables are ready, the whole family can pick them together and cook a simple meal with food they grew themselves."}}'::jsonb) on conflict (content_unit_id) do nothing;
