insert into public.content_units(id,part_id,type,data,display_order,metadata) values('34d42db9-93af-41e1-b373-79ebc674ca3d','48b34ea9-10f4-422b-9bc6-a8c223dba416','question_single_choice','{"prompt":"Which item is the cheapest?","options":[{"id":"A","label":"Morning Bowl"},{"id":"B","label":"Rice Porridge"},{"id":"C","label":"Pancake Stack"},{"id":"D","label":"Breakfast Wrap"}]}'::jsonb,2,'{"toefl_task":"read_daily_life","original_slug":"rdl-lower-1","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"standard","question_index":1}'::jsonb) on conflict (id) do nothing;
