insert into public.content_units(id,part_id,type,data,display_order,metadata) values('479dd84b-dd65-4819-93a2-fe5591943818','48b34ea9-10f4-422b-9bc6-a8c223dba416','question_single_choice','{"prompt":"How much would a Veggie Omelet with a fresh juice cost?","options":[{"id":"A","label":"$7.50"},{"id":"B","label":"$8.00"},{"id":"C","label":"$9.00"},{"id":"D","label":"$9.50"}]}'::jsonb,3,'{"toefl_task":"read_daily_life","original_slug":"rdl-lower-1","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"standard","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('479dd84b-dd65-4819-93a2-fe5591943818','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The omelet is $7.50 and juice adds $1.50, so the total is $9.00 (C). A is the price of the omelet without juice. B and D do not match any combination on the menu."}}'::jsonb) on conflict (content_unit_id) do nothing;
