insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8054d4fd-236a-4c6a-bfc0-4e6df0065eb1','bfd28ea1-5de9-4e0d-a928-001c997aac2f','reading_passage','{"toefl_stimulus":"daily_life","format":"text_messages","title":"Read a chain of text messages.","heading":null,"text":"","messages":[{"sender":"Leila","time":"15:02","text":"Hey! Are we still meeting at the museum at 4?"},{"sender":"Tomas","time":"15:05","text":"Yes! But my bus is running late. Can we say 4:30?"},{"sender":"Leila","time":"15:06","text":"No problem. I''ll wait in the cafe on the ground floor."},{"sender":"Tomas","time":"15:07","text":"Great. Do you have the student discount card?"},{"sender":"Leila","time":"15:08","text":"Yep, I have two. One is for you."},{"sender":"Tomas","time":"15:10","text":"You''re the best! See you soon."}]}'::jsonb,1,'{"original_slug":"rdl-lower-2","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"standard","toefl_stimulus":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2dc5279a-a407-43d6-85e6-3b412904e566','bfd28ea1-5de9-4e0d-a928-001c997aac2f','question_single_choice','{"prompt":"Why does Tomas want to change the meeting time?","options":[{"id":"A","label":"He forgot about the plan."},{"id":"B","label":"His bus is delayed."},{"id":"C","label":"The museum closes early."},{"id":"D","label":"He has a class at 4:00."}]}'::jsonb,2,'{"toefl_task":"read_daily_life","original_slug":"rdl-lower-2","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"standard","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('2dc5279a-a407-43d6-85e6-3b412904e566','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Tomas writes that his bus is running late, so B is correct. He clearly remembers the plan (A), and nothing is said about the museum''s hours (C) or a class (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b23b40ad-edb2-459b-9aa5-a142d16af8c8','bfd28ea1-5de9-4e0d-a928-001c997aac2f','question_single_choice','{"prompt":"Where will Leila wait for Tomas?","options":[{"id":"A","label":"At the bus stop"},{"id":"B","label":"At the museum entrance"},{"id":"C","label":"At Tomas''s home"},{"id":"D","label":"In a cafe inside the museum"}]}'::jsonb,3,'{"toefl_task":"read_daily_life","original_slug":"rdl-lower-2","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"standard","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('b23b40ad-edb2-459b-9aa5-a142d16af8c8','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Leila says she will wait in the cafe on the ground floor of the museum, so D is correct. The bus stop (A), the entrance (B) and Tomas''s home (C) are not mentioned as waiting places."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('23cda6ce-d895-4d0a-9e98-ebf99673cebf','bfd28ea1-5de9-4e0d-a928-001c997aac2f','question_single_choice','{"prompt":"What does Leila have for Tomas?","options":[{"id":"A","label":"A discount card"},{"id":"B","label":"A bus ticket"},{"id":"C","label":"A cup of coffee"},{"id":"D","label":"A map of the museum"}]}'::jsonb,4,'{"toefl_task":"read_daily_life","original_slug":"rdl-lower-2","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"standard","question_index":3}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('23cda6ce-d895-4d0a-9e98-ebf99673cebf','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Leila has two student discount cards and says one is for Tomas, so A is correct. A bus ticket (B), coffee (C) and a map (D) are not mentioned."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('f92a6fb1-9e88-4f41-a233-4bd6d8600d5c','ff51905c-ec22-4ad8-af3c-99e5b81c4009','Read an Academic Passage',4,'{"toefl_task":"read_academic_passage","difficulty_tier":"standard"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('62fae49b-53a8-4d2a-a6ba-01a9b207414b','f92a6fb1-9e88-4f41-a233-4bd6d8600d5c','reading_passage','{"toefl_stimulus":"academic_passage","title":"Why Metal Feels Colder Than Wood","text":"Imagine walking into a kitchen early on a winter morning. You touch a metal spoon and a wooden spoon that have been lying side by side on the counter all night. The metal spoon feels much colder. Many people are surprised to learn that both spoons are actually the same temperature. They have been in the same room for hours, so they have both reached the temperature of the air around them.\n\nThe difference comes from how quickly each material moves heat. Your hand is warmer than the room, so heat flows from your skin into anything you touch. Metal is a good conductor, which means it carries heat away from your skin very fast. Your nerves notice this quick loss of heat, and your brain reads it as cold. Wood is a poor conductor. It takes heat from your hand slowly, so your skin stays warm and the spoon feels less cold.\n\nThis idea is useful in everyday life. Cooking pots are often made of metal so that heat travels quickly from the stove to the food, while their handles are often made of wood or plastic so that people can hold them safely.","subject":"physical science"}'::jsonb,1,'{"original_slug":"ap-lower-1","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"standard","toefl_stimulus":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('78848bc2-2011-4e05-bbef-e7030e97811c','f92a6fb1-9e88-4f41-a233-4bd6d8600d5c','question_single_choice','{"prompt":"According to the passage, why does the metal spoon feel colder than the wooden spoon?","options":[{"id":"A","label":"It was kept in a colder part of the kitchen."},{"id":"B","label":"Its temperature is lower than that of the wooden spoon."},{"id":"C","label":"It removes heat from the skin more quickly."},{"id":"D","label":"It sends cold into the hand through the nerves."}]}'::jsonb,2,'{"toefl_task":"read_academic_passage","original_slug":"ap-lower-1","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"standard","question_index":1,"skill":"factual"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('78848bc2-2011-4e05-bbef-e7030e97811c','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Paragraph 2 says metal ''carries heat away from your skin very fast'', so C is correct. The spoons lay side by side (A) and are ''the same temperature'' (B). Heat moves from the hand into the spoon, not cold into the hand (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('47ac6239-b7f7-4de5-821d-6fcf5b32f6e4','f92a6fb1-9e88-4f41-a233-4bd6d8600d5c','question_single_choice','{"prompt":"The word ''reached'' in the passage is closest in meaning to","options":[{"id":"A","label":"arrived at"},{"id":"B","label":"moved away from"},{"id":"C","label":"stretched toward"},{"id":"D","label":"increased"}]}'::jsonb,3,'{"toefl_task":"read_academic_passage","original_slug":"ap-lower-1","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"standard","question_index":2,"skill":"vocabulary"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('47ac6239-b7f7-4de5-821d-6fcf5b32f6e4','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The spoons have ''reached the temperature of the air'', meaning they have arrived at that temperature, so A is correct. B means the opposite. ''Stretched toward'' (C) is a different, physical meaning of ''reach'', and ''increased'' (D) does not describe a level that has been achieved."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('54997575-919e-4cef-b04f-99f1b0403dd1','f92a6fb1-9e88-4f41-a233-4bd6d8600d5c','question_single_choice','{"prompt":"Based on the passage, which object would probably feel coldest to touch in a cool room?","options":[{"id":"A","label":"A wool blanket"},{"id":"B","label":"A wooden table"},{"id":"C","label":"A plastic cup"},{"id":"D","label":"A metal door handle"}]}'::jsonb,4,'{"toefl_task":"read_academic_passage","original_slug":"ap-lower-1","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"standard","question_index":3,"skill":"inference"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('54997575-919e-4cef-b04f-99f1b0403dd1','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Metal is a good conductor, so it takes heat from the skin fastest and feels coldest (D). The passage describes wood as a poor conductor (B) and suggests plastic handles are safe to hold because they move heat slowly (C). A blanket (A) is not a material described as a good conductor."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d472d5be-f6e8-4696-94ff-3ae920950b79','f92a6fb1-9e88-4f41-a233-4bd6d8600d5c','question_single_choice','{"prompt":"How does paragraph 3 relate to paragraph 2?","options":[{"id":"A","label":"It disagrees with the explanation in paragraph 2."},{"id":"B","label":"It shows a practical use of the idea explained in paragraph 2."},{"id":"C","label":"It introduces a new problem that paragraph 2 did not solve."},{"id":"D","label":"It repeats the example of the spoons in more detail."}]}'::jsonb,5,'{"toefl_task":"read_academic_passage","original_slug":"ap-lower-1","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"standard","question_index":4,"skill":"relationship"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d472d5be-f6e8-4696-94ff-3ae920950b79','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Paragraph 3 applies the idea of good and poor conductors to cooking pots and their handles, so B is correct. It agrees with paragraph 2 (A), raises no new problem (C), and talks about pots rather than spoons (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('17a22ab4-727a-415d-a34f-b3a6874cfdbf','f92a6fb1-9e88-4f41-a233-4bd6d8600d5c','question_single_choice','{"prompt":"Why does the author begin the passage with the example of two spoons?","options":[{"id":"A","label":"To introduce a common experience that the passage will explain"},{"id":"B","label":"To argue that wooden spoons are better for cooking"},{"id":"C","label":"To describe how kitchens are kept warm in winter"},{"id":"D","label":"To show that people often lose kitchen tools"}]}'::jsonb,6,'{"toefl_task":"read_academic_passage","original_slug":"ap-lower-1","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"standard","question_index":5,"skill":"purpose"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('17a22ab4-727a-415d-a34f-b3a6874cfdbf','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The spoons present a familiar puzzle (one feels colder) that the rest of the passage explains, so A is correct. The author does not compare spoons for cooking (B), discuss heating kitchens (C) or mention lost tools (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('63964f6b-5584-4cfb-8448-13adfaaa2604','ff51905c-ec22-4ad8-af3c-99e5b81c4009','Complete the Words',5,'{"toefl_task":"complete_the_words","difficulty_tier":"advanced"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a994152c-cca0-4bf2-b4ca-402205596ad6','63964f6b-5584-4cfb-8448-13adfaaa2604','question_complete_words','{"prompt":"Fill in the missing letters in the paragraph.","text":"Economists distinguish between goods that are rivalrous and those that are not. A {{1}} is {{2}} because {{3}} one {{4}} eats {{5}}, nobody {{6}} can {{7}} the {{8}} sandwich. A {{9}} of {{10}}, by contrast, can be shared indefinitely without being depleted, since teaching a mathematical proof to another student does not erase it from the memory of the teacher. This characteristic explains why ideas can spread rapidly across societies, but it also complicates efforts to reward inventors, because others can often benefit from an innovation without paying for it.","blanks":[{"id":"1","stem":"sand","length":4},{"id":"2","stem":"riva","length":5},{"id":"3","stem":"wh","length":2},{"id":"4","stem":"per","length":3},{"id":"5","stem":"i","length":1},{"id":"6","stem":"el","length":2},{"id":"7","stem":"con","length":4},{"id":"8","stem":"sa","length":2},{"id":"9","stem":"pi","length":3},{"id":"10","stem":"know","length":5}],"topic":"economics"}'::jsonb,1,'{"toefl_task":"complete_the_words","original_slug":"cw-upper-1","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a994152c-cca0-4bf2-b4ca-402205596ad6','{"blanks":{"1":"wich","2":"lrous","3":"en","4":"son","5":"t","6":"se","7":"sume","8":"me","9":"ece","10":"ledge"},"stems":{"1":"sand","2":"riva","3":"wh","4":"per","5":"i","6":"el","7":"con","8":"sa","9":"pi","10":"know"},"words":{"1":"sandwich","2":"rivalrous","3":"when","4":"person","5":"it","6":"else","7":"consume","8":"same","9":"piece","10":"knowledge"}}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Full paragraph: Economists distinguish between goods that are rivalrous and those that are not. A sandwich is rivalrous because when one person eats it, nobody else can consume the same sandwich. A piece of knowledge, by contrast, can be shared indefinitely without being depleted, since teaching a mathematical proof to another student does not erase it from the memory of the teacher. This characteristic explains why ideas can spread rapidly across societies, but it also complicates efforts to reward inventors, because others can often benefit from an innovation without paying for it."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('57b71786-0381-4c6b-b87c-cba7103662cf','ff51905c-ec22-4ad8-af3c-99e5b81c4009','Read in Daily Life',6,'{"toefl_task":"read_daily_life","difficulty_tier":"advanced"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('020c6bd7-b849-450d-8559-45840473e5b6','57b71786-0381-4c6b-b87c-cba7103662cf','reading_passage','{"toefl_stimulus":"daily_life","format":"social_post","title":"Read a social media post.","heading":"Hollow Oak Community Garden","text":"Well, that''s a wrap on our first Seed Swap! Huge shout-out to everyone who braved the drizzle on Saturday. We honestly expected a handful of die-hards, but more than 80 of you turned up, and the tomato table was cleaned out before noon. Lesson learned: next year we''ll double the tomatoes and set up the tent BEFORE the clouds roll in.\n\nA few folks asked whether the leftover seeds will go to waste. Not a chance! Everything that didn''t find a home is heading to the school garden club on Pine Street. Stay tuned for our spring planting day; details coming soon!"}'::jsonb,1,'{"original_slug":"rdl-upper-1","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","toefl_stimulus":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('12949314-ef5a-437d-8a35-e352da4d1364','57b71786-0381-4c6b-b87c-cba7103662cf','question_single_choice','{"prompt":"What does the phrase ''that''s a wrap'' mean in the post?","options":[{"id":"A","label":"An event has come to an end."},{"id":"B","label":"A gift has been prepared."},{"id":"C","label":"The weather has cleared."},{"id":"D","label":"A plan has been canceled."}]}'::jsonb,2,'{"toefl_task":"read_daily_life","original_slug":"rdl-upper-1","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('12949314-ef5a-437d-8a35-e352da4d1364','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"''That''s a wrap'' is an informal way of saying something has finished; here the post looks back on a Seed Swap that already happened, so A is correct. Nothing is wrapped as a gift (B). It drizzled, so C is wrong, and the event took place, so D is wrong."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5babd9eb-c52d-46c6-85da-a31dd2bc1621','57b71786-0381-4c6b-b87c-cba7103662cf','question_single_choice','{"prompt":"What can be inferred about the organizers?","options":[{"id":"A","label":"They plan to stop offering tomato seeds."},{"id":"B","label":"They held the event indoors because of the rain."},{"id":"C","label":"They underestimated how many people would come."},{"id":"D","label":"They will sell the remaining seeds to a school club."}]}'::jsonb,3,'{"toefl_task":"read_daily_life","original_slug":"rdl-upper-1","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('5babd9eb-c52d-46c6-85da-a31dd2bc1621','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"They ''expected a handful'' of people, but more than 80 came, so they underestimated attendance (C). They plan to double the tomatoes, not stop (A). People ''braved the drizzle'' and the tent was set up late, so the event was outdoors (B). The leftover seeds are being given, not sold (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('f25e97d0-b07f-455b-bfbc-3fa2d721a74d','ff51905c-ec22-4ad8-af3c-99e5b81c4009','Read in Daily Life',7,'{"toefl_task":"read_daily_life","difficulty_tier":"advanced"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ee14faed-e8aa-4a43-a439-132dba49c6d2','f25e97d0-b07f-455b-bfbc-3fa2d721a74d','reading_passage','{"toefl_stimulus":"daily_life","format":"web_page","title":"Read a web page.","heading":"Brightwater Coworking: Membership FAQ","text":"Can I bring a guest?\nFlex members may bring one guest per visit at no charge, provided the guest signs in at reception. Additional guests are billed at the day-pass rate.\n\nWhat happens if I don''t use all my hours?\nUnused hours on the Flex plan roll over for one month only. Hours older than that expire automatically and cannot be refunded.\n\nCan I pause my membership?\nDedicated Desk members may freeze their membership for up to 60 days per year, for example during travel. Requests must be submitted at least one week before the billing date; otherwise, the freeze takes effect from the following billing cycle.\n\nIs parking included?\nStreet parking is free after 6 p.m. Monthly garage permits can be added to any plan for a fee."}'::jsonb,1,'{"original_slug":"rdl-upper-2","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","toefl_stimulus":"read_daily_life"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ac533e7e-0eac-4ca5-94ef-97a48fa02ab5','f25e97d0-b07f-455b-bfbc-3fa2d721a74d','question_single_choice','{"prompt":"According to the page, what happens to Flex hours that are not used?","options":[{"id":"A","label":"They are refunded at the end of the month."},{"id":"B","label":"They can be transferred to a guest."},{"id":"C","label":"They are exchanged for a garage permit."},{"id":"D","label":"They stay available for one more month and then expire."}]}'::jsonb,2,'{"toefl_task":"read_daily_life","original_slug":"rdl-upper-2","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('ac533e7e-0eac-4ca5-94ef-97a48fa02ab5','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Unused Flex hours ''roll over for one month only'' and then expire, so D is correct. The page says they ''cannot be refunded'' (A). Transferring hours to guests (B) or exchanging them for parking (C) is never mentioned."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('249469a2-d3eb-41d3-97b7-5744bb7b9ee5','f25e97d0-b07f-455b-bfbc-3fa2d721a74d','question_single_choice','{"prompt":"A Dedicated Desk member submits a freeze request two days before the billing date. What will most likely happen?","options":[{"id":"A","label":"The request will be rejected permanently."},{"id":"B","label":"The freeze will begin one billing cycle later than the member wanted."},{"id":"C","label":"The member will be charged the day-pass rate."},{"id":"D","label":"The freeze will be limited to 30 days."}]}'::jsonb,3,'{"toefl_task":"read_daily_life","original_slug":"rdl-upper-2","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('249469a2-d3eb-41d3-97b7-5744bb7b9ee5','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Requests made less than a week before the billing date take effect from the following cycle, so the freeze will start later (B). The page does not say late requests are rejected (A). The day-pass rate applies to extra guests (C), and the limit is 60 days per year, not 30 (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('492ecf1f-c505-4b2a-8301-b91524853b1c','f25e97d0-b07f-455b-bfbc-3fa2d721a74d','question_single_choice','{"prompt":"Which statement about guests is supported by the page?","options":[{"id":"A","label":"A Flex member who brings a second guest will pay the day-pass rate for that guest."},{"id":"B","label":"Guests must already be members of Brightwater."},{"id":"C","label":"Guests can visit for free only after 6 p.m."},{"id":"D","label":"Guests do not need to sign in."}]}'::jsonb,4,'{"toefl_task":"read_daily_life","original_slug":"rdl-upper-2","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","question_index":3}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('492ecf1f-c505-4b2a-8301-b91524853b1c','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"One guest is free and ''additional guests are billed at the day-pass rate'', so A is correct. Nothing requires guests to be members (B). The 6 p.m. time refers to street parking, not guests (C). Guests must sign in at reception, so D contradicts the page."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('bedb5661-dec9-4444-8f4e-2d95251fd60d','ff51905c-ec22-4ad8-af3c-99e5b81c4009','Read an Academic Passage',8,'{"toefl_task":"read_academic_passage","difficulty_tier":"advanced"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('52f283ba-477c-45b6-bd21-e6c6ad0a70b8','bedb5661-dec9-4444-8f4e-2d95251fd60d','reading_passage','{"toefl_stimulus":"academic_passage","title":"Managing Shared Resources Without Outside Control","text":"For decades, many scholars assumed that resources owned by no single individual, such as grazing land, forests, or fishing grounds, were doomed to be overused. The reasoning seemed straightforward: each user gains the full benefit of taking a little more, while the cost of depletion is spread among everyone. Consequently, the argument went, only private ownership or strict government regulation could prevent collapse.\n\nField studies conducted in communities across several continents, however, complicated this pessimistic view. Researchers documented mountain villages that had shared pastures for centuries, coastal settlements that rotated access to fishing spots, and farming groups that allocated irrigation water through elaborate schedules. In none of these cases had an outside authority imposed the rules; the users themselves had devised them.\n\nComparing successful and unsuccessful cases, researchers identified recurring features. Durable arrangements tended to have clearly defined boundaries indicating who was entitled to use the resource. Users could take part in modifying the rules, which made the rules better suited to local conditions and more likely to be respected. Monitoring was typically carried out by the users or by people accountable to them, and penalties for violations began mildly, escalating only for repeated offenses. Such findings do not imply that community management always works, but they suggest that the choice is not simply between private property and state control.","subject":"social science"}'::jsonb,1,'{"original_slug":"ap-upper-1","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","toefl_stimulus":"read_academic_passage"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ba6df682-7be7-46c1-b661-e12e1bfca862','bedb5661-dec9-4444-8f4e-2d95251fd60d','question_single_choice','{"prompt":"According to paragraph 3, how were rule violations typically handled in durable arrangements?","options":[{"id":"A","label":"Violators were permanently excluded from the resource."},{"id":"B","label":"Outside officials decided all punishments."},{"id":"C","label":"No penalties were used, since users trusted one another."},{"id":"D","label":"Penalties started small and became stronger for repeat offenders."}]}'::jsonb,2,'{"toefl_task":"read_academic_passage","original_slug":"ap-upper-1","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","question_index":1,"skill":"factual"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('ba6df682-7be7-46c1-b661-e12e1bfca862','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Penalties ''began mildly, escalating only for repeated offenses'', so D is correct. Permanent exclusion (A) is not mentioned, monitoring was done by users or people accountable to them rather than outside officials (B), and penalties did exist (C)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('bb9c9823-333e-44a3-a48b-cc362a8b70ad','bedb5661-dec9-4444-8f4e-2d95251fd60d','question_single_choice','{"prompt":"The word ''devised'' in the passage is closest in meaning to","options":[{"id":"A","label":"rejected"},{"id":"B","label":"invented"},{"id":"C","label":"borrowed"},{"id":"D","label":"recorded"}]}'::jsonb,3,'{"toefl_task":"read_academic_passage","original_slug":"ap-upper-1","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","question_index":2,"skill":"vocabulary"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('bb9c9823-333e-44a3-a48b-cc362a8b70ad','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The sentence contrasts rules ''imposed'' by outsiders with rules the users ''devised'' themselves, meaning they invented or created them (B). The users did not reject their own rules (A), and nothing suggests the rules were borrowed (C) or merely written down (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2f553197-ea39-42b8-8357-6d07c8c7e838','bedb5661-dec9-4444-8f4e-2d95251fd60d','question_single_choice','{"prompt":"What can be inferred about the scholars described in paragraph 1?","options":[{"id":"A","label":"They had carefully studied mountain villages and coastal settlements."},{"id":"B","label":"They believed that users of shared resources usually cooperated successfully."},{"id":"C","label":"They underestimated the ability of communities to create effective rules."},{"id":"D","label":"They opposed both private ownership and government regulation."}]}'::jsonb,4,'{"toefl_task":"read_academic_passage","original_slug":"ap-upper-1","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","question_index":3,"skill":"inference"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('2f553197-ea39-42b8-8357-6d07c8c7e838','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The scholars thought only private ownership or government control could prevent collapse, but later field studies found communities managing resources with their own rules, so the scholars underestimated communities (C). The field studies came later and challenged them (A). They expected overuse, not cooperation (B), and they supported, rather than opposed, ownership and regulation (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('aa6e6264-6549-439e-8a99-4b36af5bed56','bedb5661-dec9-4444-8f4e-2d95251fd60d','question_single_choice','{"prompt":"What is the relationship between paragraph 1 and paragraph 2?","options":[{"id":"A","label":"Paragraph 2 presents evidence that challenges the view described in paragraph 1."},{"id":"B","label":"Paragraph 2 gives examples that support the argument in paragraph 1."},{"id":"C","label":"Paragraph 2 explains the historical origins of the view in paragraph 1."},{"id":"D","label":"Paragraph 2 proposes a government policy based on paragraph 1."}]}'::jsonb,5,'{"toefl_task":"read_academic_passage","original_slug":"ap-upper-1","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","question_index":4,"skill":"relationship"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('aa6e6264-6549-439e-8a99-4b36af5bed56','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Paragraph 2 begins by saying field studies ''complicated this pessimistic view'' and describes communities that managed resources themselves, so A is correct. These examples work against, not for, the argument in paragraph 1 (B). Paragraph 2 does not discuss the history of the view (C) or propose a policy (D)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1fb4b869-5ff4-474a-8510-0f269aa47fa9','bedb5661-dec9-4444-8f4e-2d95251fd60d','question_single_choice','{"prompt":"Why does the author include the final sentence of the passage?","options":[{"id":"A","label":"To argue that community management should replace all government regulation"},{"id":"B","label":"To admit that the field studies were poorly designed"},{"id":"C","label":"To summarize the reasoning of the scholars in paragraph 1"},{"id":"D","label":"To limit the claims made from the findings while stating their wider importance"}]}'::jsonb,6,'{"toefl_task":"read_academic_passage","original_slug":"ap-upper-1","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","question_index":5,"skill":"purpose"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('1fb4b869-5ff4-474a-8510-0f269aa47fa9','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The sentence admits that community management does not ''always work'' but argues the findings widen the range of choices, so it both limits and states the significance of the findings (D). It does not call for replacing all regulation (A), criticize the studies (B), or restate the scholars'' reasoning (C)."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.sections(id,experience_id,name,display_order,metadata) values('8a715604-5a2b-47e3-aba8-0d25bf1fd93d','cbee4b4a-1169-4108-820e-1e87b5db4057','Listening: Module 1',3,'{"format":"toefl-2026","duration_mode":"fixed","type":"listening","toefl_module":"router","duration_seconds":1080,"item_count":27}'::jsonb) on conflict (id) do nothing;
