insert into public.content_units(id,part_id,type,data,display_order,metadata) values('03723e99-3dcc-48ee-9c78-747061a5c1d8','37d9d70c-d3a7-4429-b2c7-04f6d67320e4','question_single_choice','{"prompt":"Choose the best response.","options":[{"id":"A","label":"Yes, I know where it is."},{"id":"B","label":"I bought my textbooks online."},{"id":"C","label":"It closed about ten minutes ago, I''m afraid."},{"id":"D","label":"It''s next to the student center."}]}'::jsonb,2,'{"toefl_task":"listen_choose_response","original_slug":"lcr-router-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
