insert into public.content_units(id,part_id,type,data,display_order,metadata) values('76949a99-00eb-4cd8-9409-38944d73b4d6','95ba65fb-c699-4a0f-8152-33510d6bec6a','question_single_choice','{"prompt":"Choose the best response.","options":[{"id":"A","label":"It got pushed to Thursday because the professor was sick."},{"id":"B","label":"I''ll present it if you want."},{"id":"C","label":"Yes, the seminar room is on the third floor."},{"id":"D","label":"I''ve never been to that seminar."}]}'::jsonb,2,'{"toefl_task":"listen_choose_response","original_slug":"lcr-router-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
