insert into public.answer_keys(content_unit_id,correct,metadata) values('064ee4f3-f981-4b80-a7ae-53e7976563d8','{"transcript":[{"speaker":"Narrator","text":"Listen to a conversation between a student and a housing office employee."},{"speaker":"Man","text":"Hi, I''d like to ask about switching rooms. My roommate and I have really different schedules."},{"speaker":"Woman","text":"I see. Is it a conflict, or just a scheduling issue?"},{"speaker":"Man","text":"Mostly scheduling. He practices guitar late at night, and I have early shifts at the lab."},{"speaker":"Woman","text":"Well, room changes don''t open until the third week of the semester. Before that, we usually suggest a roommate agreement."},{"speaker":"Man","text":"What''s that, exactly?"},{"speaker":"Woman","text":"It''s a form you fill out together. You agree on quiet hours, guests, that kind of thing. Your resident advisor helps."},{"speaker":"Man","text":"Okay. And if it doesn''t work?"},{"speaker":"Woman","text":"Then come back after the third week, and we''ll look at open rooms."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('09b60a99-8fad-445b-a3d0-997c8f282e38','f43554e0-fc6d-49f0-b615-085a3625a12a','question_single_choice','{"prompt":"Why does the man go to the housing office?","options":[{"id":"A","label":"To complain about a noisy neighbor down the hall"},{"id":"B","label":"To ask about moving to a different room"},{"id":"C","label":"To apply for a job as a resident advisor"},{"id":"D","label":"To report a broken guitar"}]}'::jsonb,2,'{"toefl_task":"listen_conversation","original_slug":"conv-router-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
