insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ba9776c9-b5c9-49d0-8aaa-7333485ea62e','f43554e0-fc6d-49f0-b615-085a3625a12a','question_single_choice','{"prompt":"What will the man most likely do next?","options":[{"id":"A","label":"Move into an open room this week"},{"id":"B","label":"Ask his roommate to stop playing guitar entirely"},{"id":"C","label":"Change his work shifts at the lab"},{"id":"D","label":"Fill out an agreement with his roommate"}]}'::jsonb,3,'{"toefl_task":"listen_conversation","original_slug":"conv-router-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
