insert into public.answer_keys(content_unit_id,correct,metadata) values('999dd94c-8921-453e-95f2-6715773f17da','{"transcript":[{"speaker":"Narrator","text":"Listen to a conversation between two students."},{"speaker":"Woman","text":"Are you coming to dinner at the dining hall tonight?"},{"speaker":"Man","text":"I don''t think so. I''ve used up almost all my meal swipes for the month."},{"speaker":"Woman","text":"Already? It''s only the middle of October."},{"speaker":"Man","text":"I know. I picked the smallest plan to save money, but I eat on campus more than I thought."},{"speaker":"Woman","text":"You can add swipes online, you know. It''s cheaper per meal than paying at the door."},{"speaker":"Man","text":"Really? I didn''t realize that. How do I do it?"},{"speaker":"Woman","text":"Log into the student portal and look under dining services. It only takes a minute."},{"speaker":"Man","text":"Great, I''ll do it right after my next class."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
