insert into public.answer_keys(content_unit_id,correct,metadata) values('52435441-c2e7-4361-b8a0-a365be15213b','{"transcript":[{"speaker":"Narrator","text":"Listen to a conversation between a student and a librarian."},{"speaker":"Man","text":"Excuse me, I booked a group study room for three o''clock, but someone''s in it."},{"speaker":"Woman","text":"Let me check. What''s your name?"},{"speaker":"Man","text":"Daniel Okafor."},{"speaker":"Woman","text":"Hmm, your booking is for three o''clock tomorrow, not today."},{"speaker":"Man","text":"Oh no. My group is already on the way."},{"speaker":"Woman","text":"Well, room four on the second floor is free until five. I can put you in there now."},{"speaker":"Man","text":"That would be perfect. And could I keep tomorrow''s booking too?"},{"speaker":"Woman","text":"Sure, but you''ll need to check in within fifteen minutes of the start time, or the room is released."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
