insert into public.answer_keys(content_unit_id,correct,metadata) values('53433c87-369e-4d9a-a2e7-8b99bda34d8a','{"transcript":[{"speaker":"Narrator","text":"Listen to an announcement in a classroom."},{"speaker":"Speaker","text":"Before we start, a quick change to the midterm. Instead of the in-class exam we planned for next Wednesday, you''ll write a take-home essay. I''ll post the questions online on Monday morning, and you''ll have until Friday at noon to submit. The essay should be about four pages. Since you''ll have more time, I''ll be looking closely at how well you use evidence from the readings, so start reviewing your notes now."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('eeb4d1c1-3f39-4a12-812e-0f116c1d0d41','4728c61a-d8d7-48ff-bd68-d37cf0bf16fd','question_single_choice','{"prompt":"What is the main purpose of the announcement?","options":[{"id":"A","label":"To cancel the midterm"},{"id":"B","label":"To introduce a new reading list"},{"id":"C","label":"To explain a change in the midterm format"},{"id":"D","label":"To move the class to a different room"}]}'::jsonb,2,'{"toefl_task":"listen_announcement","original_slug":"ann-router-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
