insert into public.answer_keys(content_unit_id,correct,metadata) values('406dee99-b9e0-497c-84fa-eef54174f456','{"transcript":[{"speaker":"Narrator","text":"Listen to an announcement in the campus library."},{"speaker":"Speaker","text":"Attention, library users. Starting Monday, the third floor will be closed for about six weeks while we replace the carpets and lighting. The quiet study area will move to the reading room on the first floor. Books from the third floor can still be requested at the front desk, and staff will bring them down within an hour. We apologize for the noise and thank you for your patience."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c132e563-6bfb-4a79-b3d8-fb7e886eb348','59754f32-352b-45d4-b825-a37f92319e0f','question_single_choice','{"prompt":"What is the announcement mainly about?","options":[{"id":"A","label":"New library opening hours"},{"id":"B","label":"A temporary closure of part of the library"},{"id":"C","label":"A rule against noise in the library"},{"id":"D","label":"A new online book request system"}]}'::jsonb,2,'{"toefl_task":"listen_announcement","original_slug":"ann-router-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
