insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7de6d1ea-d7ef-4aa6-bc14-b27aca5dec4c','59754f32-352b-45d4-b825-a37f92319e0f','question_single_choice','{"prompt":"How can students get books from the third floor?","options":[{"id":"A","label":"By going upstairs with a staff member"},{"id":"B","label":"By waiting six weeks"},{"id":"C","label":"By ordering them online"},{"id":"D","label":"By asking at the front desk"}]}'::jsonb,3,'{"toefl_task":"listen_announcement","original_slug":"ann-router-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
