insert into public.parts(id,section_id,name,display_order,metadata) values('afc134fb-8bfc-437e-9306-727cc1e7cae3','8a715604-5a2b-47e3-aba8-0d25bf1fd93d','Listen to an Academic Talk',15,'{"toefl_task":"listen_academic_talk"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('05bea679-f68b-4cc8-a20f-c14a0eb0429e','afc134fb-8bfc-437e-9306-727cc1e7cae3','audio','{"url":"/media/toefl-2026/talk-router-1.mp3","duration_seconds":65.6,"play_once":true,"auto_start":true,"toefl_stimulus":"listen_academic_talk","speakers":["m_us3"],"context":"Listen to a talk in a biology class."}'::jsonb,1,'{"toefl_stimulus":"listen_academic_talk","original_slug":"talk-router-1"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('05bea679-f68b-4cc8-a20f-c14a0eb0429e','{"transcript":[{"speaker":"Narrator","text":"Listen to a talk in a biology class."},{"speaker":"Speaker","text":"Let''s talk about hummingbirds and a problem they face every single night. A hummingbird''s heart can beat more than a thousand times a minute while it''s flying, and it burns energy faster than almost any other animal its size. During the day, that''s fine, because it can feed on nectar every few minutes. But at night it can''t feed at all. So how does it make it to morning without running out of fuel? The answer is something called torpor. Torpor is a bit like a very short hibernation. The bird''s body temperature drops sharply, and its heartbeat slows to a fraction of its daytime rate. In this state, it uses only a tiny amount of energy. Now, torpor isn''t free. A bird in torpor is almost completely unresponsive, so it can''t escape from a predator. And waking up takes time, often twenty minutes or more, as the bird shivers its muscles to warm itself back up. That''s why hummingbirds don''t seem to enter torpor every night. They use it mainly when their energy reserves are low, for example, after a cold, rainy day when flowers were hard to find. In other words, it''s an emergency tool, not a nightly habit."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5a3e10d5-59f0-49c4-ad29-eec809c1eb05','afc134fb-8bfc-437e-9306-727cc1e7cae3','question_single_choice','{"prompt":"What is the talk mainly about?","options":[{"id":"A","label":"How hummingbirds find nectar in bad weather"},{"id":"B","label":"How hummingbirds survive nights without feeding"},{"id":"C","label":"Why hummingbirds hibernate in the winter"},{"id":"D","label":"How predators hunt hummingbirds at night"}]}'::jsonb,2,'{"toefl_task":"listen_academic_talk","original_slug":"talk-router-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('5a3e10d5-59f0-49c4-ad29-eec809c1eb05','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The talk explains torpor as the way hummingbirds get through the night when they can''t feed."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4022c5de-2035-40d6-a5c3-2bb0b46e2f59','afc134fb-8bfc-437e-9306-727cc1e7cae3','question_single_choice','{"prompt":"According to the speaker, what happens to a hummingbird in torpor?","options":[{"id":"A","label":"It flies to a warmer location."},{"id":"B","label":"Its heart rate increases to keep it warm."},{"id":"C","label":"It feeds on stored nectar."},{"id":"D","label":"Its body temperature and heart rate drop."}]}'::jsonb,3,'{"toefl_task":"listen_academic_talk","original_slug":"talk-router-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('4022c5de-2035-40d6-a5c3-2bb0b46e2f59','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The speaker says body temperature drops sharply and the heartbeat slows to a fraction of its daytime rate."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7e7fa2c3-77c5-4af1-9663-c958443a22b1','afc134fb-8bfc-437e-9306-727cc1e7cae3','question_single_choice','{"prompt":"What can be inferred about a hummingbird that had plenty to eat during the day?","options":[{"id":"A","label":"It probably will not enter torpor that night."},{"id":"B","label":"It will enter torpor earlier than usual."},{"id":"C","label":"It is more likely to be caught by a predator."},{"id":"D","label":"It will wake up more slowly the next morning."}]}'::jsonb,4,'{"toefl_task":"listen_academic_talk","original_slug":"talk-router-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('7e7fa2c3-77c5-4af1-9663-c958443a22b1','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Torpor is used mainly when energy reserves are low, so a well-fed bird probably doesn''t need it."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ba74536e-73dd-4f89-bb90-a80474f2c441','afc134fb-8bfc-437e-9306-727cc1e7cae3','question_single_choice','{"prompt":"Why does the speaker mention that waking up takes time?","options":[{"id":"A","label":"To explain why hummingbirds sleep late"},{"id":"B","label":"To compare torpor with hibernation"},{"id":"C","label":"To point out a cost of using torpor"},{"id":"D","label":"To describe how hummingbirds find flowers"}]}'::jsonb,5,'{"toefl_task":"listen_academic_talk","original_slug":"talk-router-1","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":4}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('ba74536e-73dd-4f89-bb90-a80474f2c441','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"It comes right after ''torpor isn''t free'', as one of the disadvantages, along with being unable to escape predators."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('ccd11349-e4db-4fe5-8891-0779a5d97d08','8a715604-5a2b-47e3-aba8-0d25bf1fd93d','Listen to an Academic Talk',16,'{"toefl_task":"listen_academic_talk"}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0d468efa-6e9c-415c-874e-fef47ea4d166','ccd11349-e4db-4fe5-8891-0779a5d97d08','audio','{"url":"/media/toefl-2026/talk-router-2.mp3","duration_seconds":77.9,"play_once":true,"auto_start":true,"toefl_stimulus":"listen_academic_talk","speakers":["f_us2"],"context":"Listen to a talk in a business class."}'::jsonb,1,'{"toefl_stimulus":"listen_academic_talk","original_slug":"talk-router-2"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('0d468efa-6e9c-415c-874e-fef47ea4d166','{"transcript":[{"speaker":"Narrator","text":"Listen to a talk in a business class."},{"speaker":"Speaker","text":"Today I want to look at a pricing strategy you''ve almost certainly experienced without noticing: the loss leader. A loss leader is a product that a store sells at a very low price, sometimes below what the store paid for it. That sounds like a bad business decision, right? Why would anyone sell something at a loss? The logic is that the cheap item gets customers through the door. Think of a supermarket that advertises milk or eggs at an unusually low price. People come in for the bargain, but once they''re inside, very few walk out with only milk. They pick up bread, snacks, and cleaning supplies, and those items carry normal or even high profit margins. So the store loses a little on the milk and makes it back on everything else. Notice that stores usually choose everyday items for this, things people buy often and know the price of. If the price of milk drops, shoppers notice right away. A discount on something unusual, like a specialty spice, wouldn''t attract nearly as many people. Of course, the strategy has risks. Some shoppers, sometimes called cherry pickers, buy only the discounted item and leave. If too many customers do that, the store really does just lose money."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('bcf371c9-d646-4aad-9926-03fb2851c738','ccd11349-e4db-4fe5-8891-0779a5d97d08','question_single_choice','{"prompt":"What is the main topic of the talk?","options":[{"id":"A","label":"How supermarkets set the price of milk"},{"id":"B","label":"Why shoppers prefer specialty products"},{"id":"C","label":"A strategy of selling some products cheaply to attract customers"},{"id":"D","label":"How stores reduce the cost of everyday items"}]}'::jsonb,2,'{"toefl_task":"listen_academic_talk","original_slug":"talk-router-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('bcf371c9-d646-4aad-9926-03fb2851c738','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The whole talk explains the loss leader, a cheap item that brings customers into the store."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f3c601d3-4fc4-4388-8efe-45c40c81a516','ccd11349-e4db-4fe5-8891-0779a5d97d08','question_single_choice','{"prompt":"According to the speaker, how does a store make up for the money it loses on a loss leader?","options":[{"id":"A","label":"Customers buy other items with higher profit margins."},{"id":"B","label":"Suppliers pay the store for advertising."},{"id":"C","label":"The store raises the price of milk later."},{"id":"D","label":"Customers pay a membership fee."}]}'::jsonb,3,'{"toefl_task":"listen_academic_talk","original_slug":"talk-router-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":2}'::jsonb) on conflict (id) do nothing;
