insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e4a8e4fc-5321-40c2-9e82-caebfbc6d7be','ccd11349-e4db-4fe5-8891-0779a5d97d08','question_single_choice','{"prompt":"Why does the speaker mention a specialty spice?","options":[{"id":"A","label":"To give an example of a high-profit item"},{"id":"B","label":"To show that shoppers enjoy unusual products"},{"id":"C","label":"To describe what cherry pickers usually buy"},{"id":"D","label":"To illustrate a poor choice for a loss leader"}]}'::jsonb,4,'{"toefl_task":"listen_academic_talk","original_slug":"talk-router-2","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","question_index":3}'::jsonb) on conflict (id) do nothing;
