insert into public.answer_keys(content_unit_id,correct,metadata) values('e6819c11-7e6f-4836-a2b4-22eee09cd540','{"transcript":[{"speaker":"Narrator","text":"Listen to a conversation between two students."},{"speaker":"Woman","text":"Hi, Sam. Why are you walking? Where''s your bike?"},{"speaker":"Man","text":"It has a flat tire. I think I rode over some glass."},{"speaker":"Woman","text":"Oh no. Do you know about the bike shop in the student center?"},{"speaker":"Man","text":"No. Is it expensive?"},{"speaker":"Woman","text":"It''s free for students. They give you the tools and show you how to fix it."},{"speaker":"Man","text":"That''s great. When is it open?"},{"speaker":"Woman","text":"Every afternoon from one to six."},{"speaker":"Man","text":"Perfect. I''ll take my bike there after lunch."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
