insert into public.answer_keys(content_unit_id,correct,metadata) values('d64d89d2-b315-4f52-b5b7-b5aea9354494','{"transcript":[{"speaker":"Narrator","text":"Listen to a conversation between a student and a receptionist at the campus health clinic."},{"speaker":"Man","text":"Hello, I''d like to make an appointment with a doctor. I''ve had a sore throat for three days."},{"speaker":"Woman","text":"Okay. Do you have a fever?"},{"speaker":"Man","text":"A little, last night."},{"speaker":"Woman","text":"We have an opening tomorrow at ten in the morning. Is that all right?"},{"speaker":"Man","text":"I have a class then. Is there anything later?"},{"speaker":"Woman","text":"Yes, tomorrow there''s one at two thirty."},{"speaker":"Man","text":"That works. Should I bring anything?"},{"speaker":"Woman","text":"Just your student card and a list of any medicine you''re taking."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
