insert into public.answer_keys(content_unit_id,correct,metadata) values('8bce713b-0570-4cbf-979b-939627e75e2b','{"transcript":[{"speaker":"Narrator","text":"Listen to an announcement on campus."},{"speaker":"Speaker","text":"Hello, students. This Friday, the main dining hall is having an international food night. Students from the cultural clubs will cook dishes from more than ten countries. Dinner is from five to eight, and it''s free with your meal plan. If you''d like to help cook, please sign up at the dining hall entrance by Wednesday."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
