insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6a2638b6-754b-4173-99af-9fd302f92013','62b5437c-02a2-475e-8aae-bc66f6ecb630','audio','{"url":"/media/toefl-2026/talk-lower-1.mp3","duration_seconds":54.3,"play_once":true,"auto_start":true,"toefl_stimulus":"listen_academic_talk","speakers":["f_us1"],"context":"Listen to a talk in a history class."}'::jsonb,1,'{"toefl_stimulus":"listen_academic_talk","original_slug":"talk-lower-1","difficulty_tier":"standard"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('6a2638b6-754b-4173-99af-9fd302f92013','{"transcript":[{"speaker":"Narrator","text":"Listen to a talk in a history class."},{"speaker":"Speaker","text":"Today we''re going to talk about early lighthouses. For thousands of years, sailors needed a way to find safe harbors at night. The first lighthouses were very simple. People lit large wood fires on hills or on top of stone towers near the coast. Sailors could see the fire from far away and know where land was. But fires had problems. They used a lot of wood, and they were hard to keep burning in wind and rain. Later, people used oil lamps and candles inside glass rooms at the top of the towers. These were easier to protect from the weather. Then, in the eighteen twenties, a French scientist designed a special glass lens. It made the light much brighter, so ships could see it from more than twenty miles away. This lens changed lighthouses all over the world."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('58847015-4edc-495e-8183-6a11fd3acf15','62b5437c-02a2-475e-8aae-bc66f6ecb630','question_single_choice','{"prompt":"What is the talk mainly about?","options":[{"id":"A","label":"How lighthouses developed over time"},{"id":"B","label":"Why sailors got lost at night"},{"id":"C","label":"How to build a stone tower"},{"id":"D","label":"Famous French scientists"}]}'::jsonb,2,'{"toefl_task":"listen_academic_talk","original_slug":"talk-lower-1","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"standard","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('58847015-4edc-495e-8183-6a11fd3acf15','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The talk moves from wood fires to oil lamps to a new lens, showing how lighthouses changed."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ae6d34b0-659f-4ef7-9d0a-1d4c2acdaf49','62b5437c-02a2-475e-8aae-bc66f6ecb630','question_single_choice','{"prompt":"What was one problem with using fires in early lighthouses?","options":[{"id":"A","label":"They were too bright for sailors."},{"id":"B","label":"They could not be seen from hills."},{"id":"C","label":"They were difficult to keep burning in bad weather."},{"id":"D","label":"They were only allowed in France."}]}'::jsonb,3,'{"toefl_task":"listen_academic_talk","original_slug":"talk-lower-1","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"standard","question_index":2}'::jsonb) on conflict (id) do nothing;
