insert into public.answer_keys(content_unit_id,correct,metadata) values('c18f0c32-2f12-426a-b74c-786b0485496b','{"transcript":[{"speaker":"Narrator","text":"Listen to a conversation between two students working on a group project."},{"speaker":"Woman","text":"Have you heard from Marcus about his section of the report?"},{"speaker":"Man","text":"Not a word. I''ve sent him three messages since Monday."},{"speaker":"Woman","text":"We present on Thursday. I''m starting to think we should split his part between us."},{"speaker":"Man","text":"I''d rather not step on his toes, though. He did say he was working on it."},{"speaker":"Woman","text":"Saying and doing are two different things. If he shows up with nothing, we''re the ones who look bad."},{"speaker":"Man","text":"Fair enough. How about this: if we don''t have a draft from him by tomorrow night, we divide it up."},{"speaker":"Woman","text":"Deal. And maybe we mention it to the professor afterward."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d0d5845d-1da6-41fc-89eb-18bcbab87ee0','7cbaf554-059b-4842-9d70-f716d4b0b363','question_single_choice','{"prompt":"Why is the man unwilling at first to take over Marcus''s section?","options":[{"id":"A","label":"He thinks the professor won''t allow it."},{"id":"B","label":"He doesn''t want to offend Marcus."},{"id":"C","label":"He is too busy with his own section."},{"id":"D","label":"He believes the report is already finished."}]}'::jsonb,2,'{"toefl_task":"listen_conversation","original_slug":"conv-upper-1","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d0d5845d-1da6-41fc-89eb-18bcbab87ee0','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"''I''d rather not step on his toes'' means he doesn''t want to upset Marcus by taking over his work."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('968c1c30-34d1-4bda-9ed8-5d7c323224ed','7cbaf554-059b-4842-9d70-f716d4b0b363','question_single_choice','{"prompt":"What do the speakers decide to do?","options":[{"id":"A","label":"Wait one more day before dividing Marcus''s work"},{"id":"B","label":"Ask the professor to postpone the presentation"},{"id":"C","label":"Remove Marcus from the group immediately"},{"id":"D","label":"Present without Marcus''s section"}]}'::jsonb,3,'{"toefl_task":"listen_conversation","original_slug":"conv-upper-1","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","question_index":2}'::jsonb) on conflict (id) do nothing;
