insert into public.answer_keys(content_unit_id,correct,metadata) values('eaf43a2b-dfcf-4cc4-b917-bdc17b234466','{"transcript":[{"speaker":"Narrator","text":"Listen to a conversation between a student and a study abroad advisor."},{"speaker":"Man","text":"I was hoping to study in Lisbon next spring, but the program page says applications closed last week."},{"speaker":"Woman","text":"That''s for the university exchange. There''s also a direct enrollment option that runs on a later cycle."},{"speaker":"Man","text":"What''s the catch?"},{"speaker":"Woman","text":"Your credits don''t transfer automatically. You''d need each course approved by your department beforehand."},{"speaker":"Man","text":"That sounds like a lot of running around."},{"speaker":"Woman","text":"It can be, but students who plan ahead usually manage. The deadline isn''t until the first of November."},{"speaker":"Man","text":"Then I''d better get my advisor''s signature this week."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
