insert into public.answer_keys(content_unit_id,correct,metadata) values('70b7db71-9280-469d-9833-3fe75237a2ae','{"transcript":[{"speaker":"Narrator","text":"Listen to an announcement in a biology lab."},{"speaker":"Speaker","text":"One more thing before you go. Several groups have been leaving the microscopes on the benches with the lights still running. Those bulbs aren''t cheap, and the department won''t keep replacing them forever. From now on, each group will sign out a microscope and sign it back in at the end of the session. If one comes back damaged or left on, that group loses bench time next week. I''d rather not have to enforce that, so let''s make it a non-issue."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6c178d3e-d7d2-49cb-b08a-c574e48634d7','f695aa32-2750-4386-af23-213b21fb1660','question_single_choice','{"prompt":"Why does the instructor make the announcement?","options":[{"id":"A","label":"To announce that new microscopes have arrived"},{"id":"B","label":"To introduce a rule about using the microscopes"},{"id":"C","label":"To change the lab schedule for next week"},{"id":"D","label":"To ask students to buy replacement bulbs"}]}'::jsonb,2,'{"toefl_task":"listen_announcement","original_slug":"ann-upper-1","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","question_index":1}'::jsonb) on conflict (id) do nothing;
