insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c01f7a2c-1666-4048-94a7-350dd27df3b1','f695aa32-2750-4386-af23-213b21fb1660','question_single_choice','{"prompt":"What does the instructor imply when he says he''d rather not have to enforce the rule?","options":[{"id":"A","label":"He hopes students will follow it so no penalty is needed."},{"id":"B","label":"He doesn''t think the rule is fair."},{"id":"C","label":"Another instructor will enforce it instead."},{"id":"D","label":"The rule only applies to some groups."}]}'::jsonb,3,'{"toefl_task":"listen_announcement","original_slug":"ann-upper-1","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","question_index":2}'::jsonb) on conflict (id) do nothing;
