insert into public.answer_keys(content_unit_id,correct,metadata) values('2f69160c-9524-4732-baeb-69bc344fe940','{"transcript":[{"speaker":"Narrator","text":"Listen to an announcement on the campus radio station."},{"speaker":"Speaker","text":"The psychology department is recruiting volunteers for a study on sleep and memory. Participants will wear a light wrist monitor for two weeks and complete a short online puzzle each morning. There''s no lab visit beyond the first briefing. Those who finish the full two weeks receive a forty dollar bookstore voucher; partial completion, unfortunately, doesn''t qualify. Spaces are limited, and the last round filled within days, so if you''re interested, don''t sit on it. The sign-up link is on the department''s homepage."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('820977d9-ed9f-4e26-bc2c-e4228b28740d','7a2ee3a0-891f-4364-a0d2-4ba3a9e77f42','question_single_choice','{"prompt":"What must participants do to receive the voucher?","options":[{"id":"A","label":"Visit the lab every morning"},{"id":"B","label":"Score well on the puzzles"},{"id":"C","label":"Complete the entire two-week study"},{"id":"D","label":"Recruit another volunteer"}]}'::jsonb,2,'{"toefl_task":"listen_announcement","original_slug":"ann-upper-2","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('820977d9-ed9f-4e26-bc2c-e4228b28740d','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Only those who finish the full two weeks get the voucher; partial completion doesn''t qualify. The puzzles are done online, not in the lab."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('51965c57-6344-40db-be61-12777dfe0ec2','7a2ee3a0-891f-4364-a0d2-4ba3a9e77f42','question_single_choice','{"prompt":"What does the speaker mean when she says ''don''t sit on it''?","options":[{"id":"A","label":"Don''t tell anyone else about the study."},{"id":"B","label":"Don''t stay seated during the briefing."},{"id":"C","label":"Don''t complete the puzzle too quickly."},{"id":"D","label":"Don''t wait long before signing up."}]}'::jsonb,3,'{"toefl_task":"listen_announcement","original_slug":"ann-upper-2","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","question_index":2}'::jsonb) on conflict (id) do nothing;
