insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0d99fc0d-4713-4257-a4a6-7ba2708d082c','aa0628f6-b05e-41dc-bcb5-37afbbde19c6','audio','{"url":"/media/toefl-2026/talk-upper-1.mp3","duration_seconds":84.4,"play_once":true,"auto_start":true,"toefl_stimulus":"listen_academic_talk","speakers":["m_us1"],"context":"Listen to a talk in an earth science class."}'::jsonb,1,'{"toefl_stimulus":"listen_academic_talk","original_slug":"talk-upper-1","difficulty_tier":"advanced"}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('0d99fc0d-4713-4257-a4a6-7ba2708d082c','{"transcript":[{"speaker":"Narrator","text":"Listen to a talk in an earth science class."},{"speaker":"Speaker","text":"I''d like to clear up a misconception that trips up a lot of students: the idea that water always freezes at zero degrees Celsius. Pure water can actually stay liquid well below that point, down to around minus forty in some cases. We call this supercooled water. So what''s going on? For ice to form, water molecules need to line up into a crystal, and that process has to start somewhere. In everyday life it almost always starts on something else, like a speck of dust, a scratch in a container, or a grain of pollen. These starting points are called nuclei. Without them, the molecules jostle around but never quite lock into place. This matters enormously for weather. Clouds high in the atmosphere are often full of supercooled droplets, simply because there aren''t enough suitable particles for ice to form on. When a few ice crystals do appear, they grow at the expense of the surrounding droplets and can eventually become heavy enough to fall. In fact, much of the rain that reaches the ground begins its life as snow up there. And here''s where it gets practical. Supercooled droplets that strike an airplane''s wing can freeze on contact, which is why icing is taken so seriously in aviation. The wing itself, in effect, becomes the nucleus."}]}'::jsonb,'{"source":"original-schood-toefl-2026"}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('12bd397a-3b94-4355-8af3-6def9fd67b09','aa0628f6-b05e-41dc-bcb5-37afbbde19c6','question_single_choice','{"prompt":"What is the main purpose of the talk?","options":[{"id":"A","label":"To describe how airplanes are de-iced"},{"id":"B","label":"To compare snow and rain"},{"id":"C","label":"To explain how pollen affects clouds"},{"id":"D","label":"To explain why water can stay liquid below its usual freezing point"}]}'::jsonb,2,'{"toefl_task":"listen_academic_talk","original_slug":"talk-upper-1","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","question_index":1}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('12bd397a-3b94-4355-8af3-6def9fd67b09','{"option_id":"D"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The speaker corrects the idea that water always freezes at zero and explains supercooling and why it matters. Airplanes, rain, and pollen are examples."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2817da92-0b99-49d1-bc19-348767b39c75','aa0628f6-b05e-41dc-bcb5-37afbbde19c6','question_single_choice','{"prompt":"According to the speaker, what is usually needed for ice crystals to begin forming?","options":[{"id":"A","label":"A temperature below minus forty"},{"id":"B","label":"A particle or surface for the crystal to start on"},{"id":"C","label":"Large amounts of rain"},{"id":"D","label":"Rapid movement of water molecules"}]}'::jsonb,3,'{"toefl_task":"listen_academic_talk","original_slug":"talk-upper-1","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","question_index":2}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('2817da92-0b99-49d1-bc19-348767b39c75','{"option_id":"B"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"Freezing almost always starts on something else, such as dust, a scratch, or pollen, called a nucleus."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('98709a10-e8b5-40c6-a5d3-f7326eba666f','aa0628f6-b05e-41dc-bcb5-37afbbde19c6','question_single_choice','{"prompt":"What can be inferred about much of the rain that falls on the ground?","options":[{"id":"A","label":"It forms only in clouds without ice."},{"id":"B","label":"It is still supercooled when it lands."},{"id":"C","label":"It was frozen at an earlier stage."},{"id":"D","label":"It contains more dust than snow does."}]}'::jsonb,4,'{"toefl_task":"listen_academic_talk","original_slug":"talk-upper-1","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","question_index":3}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('98709a10-e8b5-40c6-a5d3-f7326eba666f','{"option_id":"C"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"The speaker says much rain begins its life as snow high in the clouds, so it was frozen before it melted on the way down."}}'::jsonb) on conflict (content_unit_id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4d6e8045-bbe5-479d-86a6-44319c3e9908','aa0628f6-b05e-41dc-bcb5-37afbbde19c6','question_single_choice','{"prompt":"What does the speaker mean when he says ice crystals grow ''at the expense of'' the surrounding droplets?","options":[{"id":"A","label":"The crystals grow by taking water from the droplets."},{"id":"B","label":"The crystals are expensive to study."},{"id":"C","label":"The droplets grow faster than the crystals."},{"id":"D","label":"The droplets protect the crystals from melting."}]}'::jsonb,5,'{"toefl_task":"listen_academic_talk","original_slug":"talk-upper-1","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1","difficulty_tier":"advanced","question_index":4}'::jsonb) on conflict (id) do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('4d6e8045-bbe5-479d-86a6-44319c3e9908','{"option_id":"A"}'::jsonb,'{"source":"original-schood-toefl-2026","feedback":{"explanation":"''At the expense of'' means one thing gains while another loses; the crystals get bigger while the droplets around them shrink."}}'::jsonb) on conflict (content_unit_id) do nothing;
