insert into public.parts(id,section_id,name,display_order,metadata) values('461c7b00-aa21-48a8-b3a3-b180e15ea7cc','a21b67d0-ce05-42cb-85a2-fb481e975c01','Write an Email',2,'{"toefl_task":"write_email","task_seconds":420}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('154a1abd-a32c-40c6-b358-dd8c3eaf05da','461c7b00-aa21-48a8-b3a3-b180e15ea7cc','question_text','{"task_type":"toefl_email","prompt":"You borrowed a portable audio recorder from your university''s media center for a class project. Halfway through an interview, the recorder stopped saving files and you lost part of your recording. Your project is due next week.\n\nWrite an email to Daniel Reyes. In your email, do the following:\n- Explain what happened with the recorder.\n- Ask whether you can borrow a replacement before your deadline.\n- Suggest a way the media center could help other students avoid this problem.\n\nWrite as much as you can and in complete sentences.","scenario":"You borrowed a portable audio recorder from your university''s media center for a class project. Halfway through an interview, the recorder stopped saving files and you lost part of your recording. Your project is due next week.","to":"Daniel Reyes","to_address":"d.reyes@university.example","subject":"Problem with a borrowed recorder","goals":["Explain what happened with the recorder.","Ask whether you can borrow a replacement before your deadline.","Suggest a way the media center could help other students avoid this problem."],"task_seconds":420,"rows":12,"show_word_count":true,"placeholder":"Write your email here."}'::jsonb,1,'{"toefl_task":"write_email","original_slug":"email-test-1","difficulty":null,"difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1"}'::jsonb) on conflict (id) do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('0c1f013d-dd8d-4314-a520-b91bd5a96c35','a21b67d0-ce05-42cb-85a2-fb481e975c01','Write for an Academic Discussion',3,'{"toefl_task":"write_academic_discussion","task_seconds":600}'::jsonb) on conflict (id) do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a0da4ae4-8e4b-499e-8503-df52566cf7e0','0c1f013d-dd8d-4314-a520-b91bd5a96c35','question_text','{"task_type":"toefl_academic_discussion","prompt":"Your professor is teaching a class on public policy. Write a post responding to the professor''s question. In your response, you should express and support your opinion and make a contribution to the discussion in your own words. An effective response will contain at least 100 words.\n\nDr. Lindqvist: This week we have been looking at how cities pay for public services. A few cities have made buses and trains completely free for everyone, covering the cost through general taxes instead of fares. Supporters say this reduces traffic and helps residents with lower incomes. Critics argue that the money would do more good if it were spent on improving the service itself, for example by running buses more often. What do you think? Is making public transportation free a good use of a city''s money? Why or why not?\n\nAmara: I think free transit is worth it. In my hometown, many people drive short distances simply because buying a ticket feels like a hassle. If riding were free, more people would leave their cars at home, which would cut pollution and make the streets safer. Those benefits help everyone, not only the riders.\n\nJonah: I see the appeal, but I disagree. The buses near my apartment come only every forty minutes, so making them free would not change much for me. I would gladly pay a fare if the city used that money to add more routes and keep them on schedule. Reliable service matters more than price.","course":"public policy","professor":{"name":"Dr. Lindqvist","text":"This week we have been looking at how cities pay for public services. A few cities have made buses and trains completely free for everyone, covering the cost through general taxes instead of fares. Supporters say this reduces traffic and helps residents with lower incomes. Critics argue that the money would do more good if it were spent on improving the service itself, for example by running buses more often. What do you think? Is making public transportation free a good use of a city''s money? Why or why not?"},"students":[{"name":"Amara","text":"I think free transit is worth it. In my hometown, many people drive short distances simply because buying a ticket feels like a hassle. If riding were free, more people would leave their cars at home, which would cut pollution and make the streets safer. Those benefits help everyone, not only the riders."},{"name":"Jonah","text":"I see the appeal, but I disagree. The buses near my apartment come only every forty minutes, so making them free would not change much for me. I would gladly pay a fare if the city used that money to add more routes and keep them on schedule. Reliable service matters more than price."}],"task_seconds":600,"min_words":100,"rows":12,"show_word_count":true,"placeholder":"Write your post here."}'::jsonb,1,'{"toefl_task":"write_academic_discussion","original_slug":"disc-test-1","difficulty":null,"difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v1"}'::jsonb) on conflict (id) do nothing;
